โค้ด Python ต่อไปนี้แสดงผลอะไร?
values = [3, 1, 4, 1, 5]
total = 0
for i in range(1, len(values)):
    if values[i] > values[i - 1]:
        total += values[i] - values[i - 1]
    else:
        total -= 1
print(total)

