def f(n):
    if n <= 1:
        return 1
    return n + f(n - 2)
print(f(6))

โค้ด Python นี้เพิ่ม count ทั้งหมดกี่ครั้ง?
count = 0
for i in range(1, 5):
    for j in range(i):
        if (i + j) % 2 == 0:
            count += 1
print(count)
